 public const string Scene="Assets/TruckAirHockey/Scenes/TruckAirHockey.unity";
 static Material Mat(string name,Color color){string path="Assets/TruckAirHockey/Materials/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.color=color;mat.SetFloat("_Smoothness",.6f);return mat;}
 static PhysicsMaterial Contact(string name,float bounce,float friction){string path="Assets/TruckAirHockey/Materials/"+name+".asset";var m=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(path);if(m==null){m=new PhysicsMaterial(name);AssetDatabase.CreateAsset(m,path);}m.bounciness=bounce;m.dynamicFriction=m.staticFriction=friction;m.frictionCombine=PhysicsMaterialCombine.Minimum;m.bounceCombine=PhysicsMaterialCombine.Maximum;EditorUtility.SetDirty(m);return m;}
 static GameObject Box(string name,Vector3 p,Vector3 s,Material material,PhysicsMaterial physical=null){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=material;if(physical==null)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());else g.GetComponent<Collider>().sharedMaterial=physical;return g;}
 static void RoundedTable(Material material){
  if(!AssetDatabase.IsValidFolder("Assets/TruckAirHockey/Meshes"))AssetDatabase.CreateFolder("Assets/TruckAirHockey","Meshes");
  const string path="Assets/TruckAirHockey/Meshes/Rounded tabletop.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name="Rounded air hockey tabletop"};AssetDatabase.CreateAsset(mesh,path);}else mesh.Clear();
  const int steps=24,count=4*(steps+1);var vertices=new Vector3[count+1];var uv=new Vector2[count+1];var triangles=new int[count*3];vertices[0]=new Vector3(0,.02f,0);uv[0]=new Vector2(.5f,.5f);int index=1;
  for(int corner=0;corner<4;corner++){int sx=corner==0||corner==3?1:-1,sz=corner<2?1:-1;var center=new Vector3(sx*9.5f,.02f,sz*3.5f);for(int i=0;i<=steps;i++){float angle=(corner+i/(float)steps)*Mathf.PI*.5f;var v=center+new Vector3(Mathf.Cos(angle)*2.5f,0,Mathf.Sin(angle)*2.5f);vertices[index]=v;uv[index]=new Vector2(v.x/24+.5f,v.z/12+.5f);index++;}}
  for(int i=0;i<count;i++){triangles[i*3]=0;triangles[i*3+1]=(i+1)%count+1;triangles[i*3+2]=i+1;}mesh.vertices=vertices;mesh.uv=uv;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);var g=new GameObject("Smooth rounded tabletop");g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=material;
 }
 static void CurvedRails(Material paint,PhysicsMaterial physical){
  // Reuse the original Hockey rink's 2.5-radius, overlapping chord-board approach.
  for(int sx=-1;sx<=1;sx+=2)for(int sz=-1;sz<=1;sz+=2){var center=new Vector3(sx*9.5f,.5f,sz*3.5f);for(int i=0;i<12;i++){float a=i*Mathf.PI/24,b=(i+1)*Mathf.PI/24;var p=center+new Vector3(sx*Mathf.Cos(a)*2.5f,0,sz*Mathf.Sin(a)*2.5f);var q=center+new Vector3(sx*Mathf.Cos(b)*2.5f,0,sz*Mathf.Sin(b)*2.5f);var board=Box("Rail rounded corner",(p+q)*.5f,new Vector3((q-p).magnitude+.035f,1,.25f),paint,physical);board.transform.rotation=Quaternion.Euler(0,-Mathf.Atan2(q.z-p.z,q.x-p.x)*Mathf.Rad2Deg,0);}}
 }
 public static void CreateBuild(){Create();SportsBuilder.Build();}
 public static void Create(){Directory.CreateDirectory("Assets/TruckAirHockey/Scenes");Directory.CreateDirectory("Assets/TruckAirHockey/Materials");var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var table=Mat("Teal smooth table",new Color(.055f,.28f,.32f));var rail=Mat("Ivory rails",new Color(.83f,.91f,.92f));var dark=Mat("Dark plinth",new Color(.012f,.025f,.038f));var red=Mat("Red line",new Color(.9f,.15f,.16f));var blue=Mat("Blue mallet",new Color(.15f,.8f,1));var orange=Mat("Orange mallet",new Color(1,.55f,.13f));var puckPaint=Mat("Luminous puck",new Color(.95f,.97f,.55f));var rails=Contact("Crisp rails",.98f,0);var puckMat=Contact("Air puck",.96f,0);var truckMat=Contact("Mallet contact",.55f,.01f);
  Box("Table plinth",new Vector3(0,-.45f,0),new Vector3(27,.8f,15),dark);RoundedTable(table);Box("Center line",new Vector3(0,.027f,0),new Vector3(.08f,.012f,11.8f),red);for(int side=-1;side<=1;side+=2){Box("Half marking",new Vector3(side*6,.03f,0),new Vector3(.035f,.012f,11.7f),rail);Box("Rail long",new Vector3(0,.5f,side*6),new Vector3(19,1,.25f),rail,rails);for(int z=-1;z<=1;z+=2)Box("Rail end",new Vector3(side*12,.5f,z*2.8f),new Vector3(.25f,1,1.4f),rail,rails);Box("Goal back",new Vector3(side*13.65f,.5f,0),new Vector3(.2f,1,4.4f),rail,rails);for(int z=-1;z<=1;z+=2){Box("Goal side",new Vector3(side*12.8f,.5f,z*2.1f),new Vector3(1.8f,1,.18f),rail,rails);Box("Goal post",new Vector3(side*12,.5f,z*2.1f),new Vector3(.13f,1,.13f),red,rails);}Box("Goal target",new Vector3(side*11.5f,.03f,0),new Vector3(.7f,.012f,4),side<0?blue:orange);}
  CurvedRails(rail,rails);
  // Air holes are visual only and never introduce tabletop collision friction.
  for(int x=-11;x<=11;x+=2)for(int z=-5;z<=5;z+=2)Box("Air hole",new Vector3(x,.026f,z),new Vector3(.045f,.008f,.045f),rail);
  var root=new GameObject("Truck Air Hockey Authority");var m=root.AddComponent<AirHockeyMatch>();m.cornerRadius=2.5f;m.settings=root.AddComponent<SportsSettings>();m.feedback=root.AddComponent<SportsFeedback>();m.feedback.settings=m.settings;m.feedback.clips=HockeyAudioAuthoring.Create();SportsUIAuthoring.Events(root);
  m.truckBarriers=new Collider[3];m.truckBarriers[0]=Box("Truck-only center barrier",new Vector3(0,.5f,0),new Vector3(.2f,1,12),rail,truckMat).GetComponent<Collider>();for(int i=0;i<2;i++)m.truckBarriers[i+1]=Box("Truck-only goal barrier",new Vector3(i==0?-11.85f:11.85f,.5f,0),new Vector3(.15f,1,4.05f),rail,truckMat).GetComponent<Collider>();foreach(var c in m.truckBarriers)c.GetComponent<Renderer>().enabled=false;
  var puck=GameObject.CreatePrimitive(PrimitiveType.Cylinder);puck.name="Air Hockey Puck";puck.transform.position=new Vector3(-3,.22f,0);puck.transform.localScale=new Vector3(.86f,.11f,.86f);puck.GetComponent<Renderer>().sharedMaterial=puckPaint;UnityEngine.Object.DestroyImmediate(puck.GetComponent<Collider>());var shape=puck.AddComponent<MeshCollider>();shape.sharedMesh=puck.GetComponent<MeshFilter>().sharedMesh;shape.convex=true;shape.sharedMaterial=puckMat;m.puck=puck.AddComponent<Rigidbody>();m.puck.useGravity=false;m.puck.mass=.7f;m.puck.constraints=RigidbodyConstraints.FreezePositionY|RigidbodyConstraints.FreezeRotation;m.puck.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;m.puck.interpolation=RigidbodyInterpolation.Interpolate;m.puck.solverIterations=12;m.puck.maxDepenetrationVelocity=3;m.puckContact=puck.AddComponent<AirHockeyPuck>();m.puckContact.match=m;m.puckContact.body=m.puck;
  m.trucks=new AirHockeyTruck[2];m.agents=new AirHockeyAI[2];m.paint=new Renderer[2];for(int i=0;i<2;i++){var g=new GameObject(i==0?"Blue Truck Mallet":"Orange Truck Mallet");HockeyAuthoring.TruckGeometry(g.transform,1.9f);g.transform.position=new Vector3(i==0?-6:6,.36f,0);g.transform.rotation=Quaternion.Euler(0,i==0?90:-90,0);var body=g.AddComponent<Rigidbody>();body.mass=3;body.useGravity=false;body.constraints=RigidbodyConstraints.FreezePositionY|RigidbodyConstraints.FreezeRotation;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.interpolation=RigidbodyInterpolation.Interpolate;body.solverIterations=12;body.maxDepenetrationVelocity=3;var box=g.AddComponent<BoxCollider>();box.size=new Vector3(.95f,.55f,1.95f);box.sharedMaterial=truckMat;m.paint[i]=g.GetComponentsInChildren<MeshRenderer>().First(r=>r.name=="Cab");var t=g.AddComponent<AirHockeyTruck>();t.match=m;t.body=body;t.shape=box;t.slot=i;m.trucks[i]=t;var ai=g.AddComponent<AirHockeyAI>();ai.match=m;ai.truck=t;m.agents[i]=ai;}
  var camera=HockeyAuthoring.Camera();camera.name="Air Hockey Table Camera";camera.transform.position=new Vector3(0,21,-13);camera.transform.LookAt(Vector3.zero);camera.GetComponent<SportsCameraFit>().worldWidth=33;camera.GetComponent<SportsCameraFit>().worldHeight=21;UI(m);EditorSceneManager.SaveScene(scene,Scene);AssetDatabase.SaveAssets();Debug.Log("AH_SAVED_SCENE_AUTHORED");
 }
 static void UI(AirHockeyMatch match){var canvas=SportsUIAuthoring.Canvas();var m=canvas.gameObject.AddComponent<AirHockeyMenus>();match.menus=m;m.match=match;m.settings=match.settings;m.feedback=match.feedback;m.pages=new GameObject[9];var p=SportsUIAuthoring.Page("Setup",m.transform,"TRUCK AIR HOCKEY","FIRST TO 7 • 1v1 • Your truck is the mallet • Each stays in its half");m.pages[0]=p;m.modeLabel=SportsUIAuthoring.Button(p.transform,"HUMAN vs AI","mode",new Vector2(0,210),new Vector2(1160,60)).normalTextObj;m.names=new TMP_InputField[2];m.sourceLabels=new TMP_Text[2];m.levelLabels=new TMP_Text[2];m.colorLabels=new TMP_Text[2];for(int i=0;i<2;i++){float x=i==0?-330:330;m.names[i]=SportsUIAuthoring.Name(p.transform,"PARTICIPANT "+(i+1),match.players[i].name,new Vector2(x,85));m.sourceLabels[i]=SportsUIAuthoring.Button(p.transform,"SOURCE","source"+i,new Vector2(x,-10)).normalTextObj;m.levelLabels[i]=SportsUIAuthoring.Button(p.transform,"NORMAL","level"+i,new Vector2(x,-105)).normalTextObj;m.colorLabels[i]=SportsUIAuthoring.Button(p.transform,"COLOR","color"+i,new Vector2(x,-200)).normalTextObj;}SportsUIAuthoring.Button(p.transform,"SPORTS","front",new Vector2(-480,-365),new Vector2(280,60));SportsUIAuthoring.Button(p.transform,"RULES / CONTROLS","help",new Vector2(0,-365),new Vector2(420,60));SportsUIAuthoring.Button(p.transform,"START","start",new Vector2(480,-365),new Vector2(280,60));
  for(int i=0;i<2;i++){int index=i==0?1:7;p=SportsUIAuthoring.Page(i==0?"Join":"Disconnect",m.transform,i==0?"JOIN INPUT SOURCES":"CONTROLLER DISCONNECTED","Reconnect or explicitly reassign • Release controls before confirming");m.pages[index]=p;var t=SportsUIAuthoring.Text("Sources",p.transform,"",new Vector2(1300,340),new Vector2(0,60),27);if(i==0)m.joinText=t;else m.disconnectText=t;for(int k=0;k<2;k++)SportsUIAuthoring.Button(p.transform,"REASSIGN "+(k+1),"reassign"+k,new Vector2(k==0?-330:330,-185));SportsUIAuthoring.Button(p.transform,i==0?"BACK":"SPORTS",i==0?"back":"front",new Vector2(-330,-360));SportsUIAuthoring.Button(p.transform,i==0?"START":"RESUME",i==0?"start":"resume",new Vector2(330,-360));}
  m.pages[2]=SportsUIAuthoring.Rect("Play",m.transform,new Vector2(1920,1080),Vector2.zero);m.hud=SportsUIAuthoring.Rect("Air Hockey HUD",m.transform,new Vector2(1920,1080),Vector2.zero);m.scoreText=SportsUIAuthoring.Text("Score",m.hud.transform,"",new Vector2(1500,70),new Vector2(0,480),40);m.serveText=SportsUIAuthoring.Text("Serving side",m.hud.transform,"",new Vector2(1500,50),new Vector2(0,410),25);m.noticeText=SportsUIAuthoring.Text("Notice",m.hud.transform,"",new Vector2(1500,60),new Vector2(0,-405),29);SportsUIAuthoring.Text("Controls",m.hud.transform,"Drive into the puck • Opposite throttle brakes then reverses • Esc / Start pauses",new Vector2(1550,50),new Vector2(0,-470),22);
  p=SportsUIAuthoring.Page("Pause",m.transform,"PAUSED","Scores, serving side and physical state are preserved");m.pages[3]=p;string[] labels={"RESUME","RULES / CONTROLS","SETTINGS","RESTART MATCH","SPORT SELECTION"},keys={"resume","help","settings","restart","front"};for(int i=0;i<5;i++)SportsUIAuthoring.Button(p.transform,labels[i],keys[i],new Vector2(0,170-i*90));p=SportsUIAuthoring.Page("Help",m.transform,"AIR HOCKEY RULES / CONTROLS");m.pages[4]=p;SportsUIAuthoring.Text("Rules",p.transform,AirHockeyMenus.Rules,new Vector2(1300,625),new Vector2(0,-30),25);SportsUIAuthoring.Button(p.transform,"BACK","back",new Vector2(0,-390));SportsUIAuthoring.SettingsPage(m,5);
  p=SportsUIAuthoring.Page("Confirm",m.transform,"ARE YOU SURE?");m.pages[6]=p;m.confirmText=SportsUIAuthoring.Text("Question",p.transform,"",new Vector2(1300,200),new Vector2(0,50),32);SportsUIAuthoring.Button(p.transform,"CANCEL","no",new Vector2(-330,-230));SportsUIAuthoring.Button(p.transform,"CONFIRM","yes",new Vector2(330,-230));p=SportsUIAuthoring.Page("Result",m.transform,"MATCH WON","First to 7 • Configuration retained • Opening serve alternates");m.pages[8]=p;m.resultTitle=p.transform.Find("Title").GetComponent<RectTransform>();m.resultText=SportsUIAuthoring.Text("Winner",p.transform,"",new Vector2(1300,180),new Vector2(0,60),36);SportsUIAuthoring.Button(p.transform,"REMATCH • ALTERNATE SERVE","rematch",new Vector2(0,-100),new Vector2(850,65));SportsUIAuthoring.Button(p.transform,"CHANGE SETUP","setup",new Vector2(0,-210));SportsUIAuthoring.Button(p.transform,"SPORT SELECTION","front",new Vector2(0,-320));foreach(var page in m.pages)page.SetActive(false);m.pages[0].SetActive(true);m.hud.SetActive(false);
 }
 public static void Validate(){AirHockeyFixtures.Run();var scene=EditorSceneManager.OpenScene(Scene);foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Air Hockey missing script: "+t.name);var m=UnityEngine.Object.FindAnyObjectByType<AirHockeyMatch>();if(m==null||m.trucks.Length!=2||m.agents.Length!=2||m.players.Length!=2||m.paint.Length!=2||m.truckBarriers.Length!=3||m.puck==null||m.menus.names.Length!=2||m.feedback.clips.Length!=7||m.feedback.clips.Any(c=>c==null))throw new Exception("Air Hockey incomplete references");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1||UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length!=1)throw new Exception("Air Hockey listener/events invalid");foreach(var truck in m.trucks){var rr=truck.GetComponentsInChildren<MeshRenderer>();if(rr.Any(r=>r.name.Contains("mallet bumper")||r.name.Contains("Stick")))throw new Exception("Air Hockey must use the truck itself, no attachment");var bounds=rr[0].bounds;foreach(var r in rr)bounds.Encapsulate(r.bounds);var delta=bounds.center-truck.transform.position;delta.y=0;if(delta.magnitude>.12f)throw new Exception("Air Hockey visible truck/body misalignment "+delta);}if(m.cornerRadius!=2.5f||UnityEngine.Object.FindObjectsByType<MeshRenderer>().Count(r=>r.name=="Rail rounded corner")!=48||GameObject.Find("Smooth rounded tabletop")==null)throw new Exception("Air Hockey rounded table/rails incomplete");Debug.Log("AH_SAVED_SCENE_VALIDATED truck-only mallets / aligned bodies / rounded table and 48 curve boards");}
}
